#!/usr/bin/env python3
"""Measure direct native pixels at recorded control rectangles; never alter images."""
from pathlib import Path
import argparse,collections,json,math
from PIL import Image
import numpy as np

def lum(rgb):
    x=[c/255 for c in rgb]
    y=[c/12.92 if c<=.04045 else ((c+.055)/1.055)**2.4 for c in x]
    return .2126*y[0]+.7152*y[1]+.0722*y[2]
def contrast(a,b):
    x,y=sorted([lum(a),lum(b)])
    return (y+.05)/(x+.05)
def pixel(rows,xy):return [int(v) for v in rows[xy[1],xy[0],:3]]
def rect_pixels(image,rect):
    x,y,w,h=rect;x0=max(0,math.ceil(x));y0=max(0,math.ceil(y));x1=min(image.shape[1],math.floor(x+w));y1=min(image.shape[0],math.floor(y+h))
    return x0,y0,x1,y1

def text_sample(image,control,omissions):
    x0,y0,x1,y1=rect_pixels(image,control.get('visible_pixel_rect',control['pixel_rect']))
    # RichTextLabel text evidence must never come from its scrollbar/style border.
    if 'scroll' in control:
        scale=control['pixel_rect'][2]/control['logical_rect'][2]
        x0+=math.ceil(4*scale);y0+=math.ceil(4*scale);y1-=math.ceil(4*scale)
        x1-=math.ceil(20*scale)
    if x1<=x0 or y1<=y0:return None
    pix=image[y0:y1,x0:x1,:3];hint=np.array([int(control['ink'][i:i+2],16) for i in [0,2,4]])
    distance=np.max(np.abs(pix.astype(int)-hint),axis=2)
    margin=8 if 'disabled' in control else 3
    if pix.shape[0]<=2*margin or pix.shape[1]<=2*margin:
        omissions.append({'name':control['name'],'text':control['text'],'reason':'Visible clipped region too small for interior glyph evidence','rect_pixels':control['pixel_rect']});return None
    eligible=np.zeros(distance.shape,dtype=bool);eligible[margin:-margin,margin:-margin]=True
    minimum=int(distance[eligible].min())
    if minimum>48:
        omissions.append({'name':control['name'],'text':control['text'],'reason':'No near-ink glyph in visible text interior; selected text reported separately when present','minimum_rgb_distance':minimum,'rect_pixels':control['pixel_rect']});return None
    ys,xs=np.where((distance==minimum)&eligible)
    idx=int(np.argmin((xs-pix.shape[1]/2)**2+(ys-pix.shape[0]/2)**2))
    gx=int(xs[idx]+x0);gy=int(ys[idx]+y0);fg=pixel(image,(gx,gy))
    # Real adjacent paper/backing from an annulus. Exclude antialias/text by
    # requiring background luminance on the opposite side and stable3x3 pixel core.
    candidates=[]
    for y in range(max(y0,gy-14),min(y1,gy+15)):
        for x in range(max(x0,gx-22),min(x1,gx+23)):
            if (x-gx)**2+(y-gy)**2<4:continue
            c=pixel(image,(x,y))
            if (lum(fg)<.4 and lum(c)<.48) or (lum(fg)>=.4 and lum(c)>.15):continue
            n=image[max(y0,y-1):min(y1,y+2),max(x0,x-1):min(x1,x+2),:3]
            if np.max(np.ptp(n.astype(int),axis=(0,1)))>9:continue
            candidates.append((contrast(fg,c),x,y,c))
    if not candidates:return None
    candidates.sort();lo=candidates[0];hi=candidates[-1]
    return {'name':control['name'],'text':control['text'],'font_size_logical':control.get('font_size'),'rect_pixels':control['pixel_rect'],'style_ink_hint':control['ink'],'actual_glyph_core':{'xy':[gx,gy],'rgb':fg,'luminance':lum(fg),'distance_from_hint_max_channel':minimum,'coverage_class':'near-solid-core' if minimum<=3 else 'strongest-rendered-antialiased-core'},'adjacent_rendered_backing_min':{'xy':[lo[1],lo[2]],'rgb':lo[3],'luminance':lum(lo[3])},'adjacent_rendered_backing_max':{'xy':[hi[1],hi[2]],'rgb':hi[3],'luminance':lum(hi[3])},'ratio_min':lo[0],'ratio_max':hi[0],'pass_5_0':lo[0]>=5.0,'disabled':control.get('disabled',False),'focus':control.get('focus',False),'background_stable_candidates':len(candidates)}
def focus_sample(image,control):
    x0,y0,x1,y1=rect_pixels(image,control.get('visible_pixel_rect',control['pixel_rect']));pix=image[y0:y1,x0:x1,:3]
    if pix.size==0:return None
    ink=np.array([23,61,69]);dist=np.max(np.abs(pix.astype(int)-ink),axis=2)
    ys,xs=np.where(dist<=2)
    if len(xs)==0:return None
    # Focus ring is an inset3px border. Avoid text by take first border pixel.
    border=(xs<10)|(ys<10)|(xs>pix.shape[1]-11)|(ys>pix.shape[0]-11)
    if not border.any():return None
    xs=xs[border];ys=ys[border];gx=int(xs[len(xs)//2]+x0);gy=int(ys[len(ys)//2]+y0);fg=pixel(image,(gx,gy))
    candidates=[]
    for dy in range(-8,9):
        for dx in range(-8,9):
            x,y=gx+dx,gy+dy
            if not (x0<=x<x1 and y0<=y<y1):continue
            c=pixel(image,(x,y))
            if lum(c)>.48:candidates.append((contrast(fg,c),x,y,c))
    if not candidates:return None
    ratio,x,y,bg=min(candidates)
    return {'name':control['name'],'rect_pixels':control['pixel_rect'],'ring':{'xy':[gx,gy],'rgb':fg,'luminance':lum(fg)},'adjacent_backing':{'xy':[x,y],'rgb':bg,'luminance':lum(bg)},'ratio':ratio,'pass_3_0':ratio>=3,'noncolor_cue':'Inset outlined focus ring; tracking separately carries ◆ and 追踪中 text'}
def main():
    p=argparse.ArgumentParser();p.add_argument('folder',type=Path);a=p.parse_args()
    trace=json.loads((a.folder/'NATIVE-TRACE.json').read_text());reports=[]
    for shot in trace['captures']:
        surface='journal' if shot.get('page') else 'map-caption'
        if surface=='map-caption' and not any(c['name']=='MapGuidanceCaption' for c in shot['controls']):continue
        data=np.asarray(Image.open(a.folder/'screenshots'/f"{shot['name']}.png").convert('RGB'))
        samples=[];focus=[];omissions=[];expected=[];not_rendered=[]
        for ctrl in shot['controls']:
            if surface=='map-caption' and ctrl['name']!='MapGuidanceCaption':continue
            if ctrl.get('text') and ctrl.get('ink') and ctrl.get('visible'):
                variants=[]
                if ctrl.get('selected_text')!=ctrl['text']:
                    variants.append(ctrl)
                else:
                    not_rendered.append({'name':ctrl['name'],'reason':'Entire body is selected; normal ink is not rendered. Selected-text treatment measured instead.'})
                if ctrl.get('selected_text'):
                    variants.append(dict(ctrl,ink=ctrl['selected_ink'],text=ctrl['selected_text'],name=ctrl['name']+' [selected-text]'))
                for variant in variants:
                    expected.append({'name':variant['name'],'text':variant['text'],'visible_pixel_rect':variant.get('visible_pixel_rect',variant['pixel_rect']),'ink_hint':variant['ink']})
                    previous=len(omissions)
                    sample=text_sample(data,variant,omissions)
                    if sample:samples.append(sample)
                    elif len(omissions)==previous:omissions.append({'name':variant['name'],'text':variant['text'],'reason':'No stable adjacent backing sample in visible interior','rect_pixels':variant['pixel_rect']})
            if ctrl.get('focus'):
                sample=focus_sample(data,ctrl)
                if sample:focus.append(sample)
        reports.append({'surface':surface,'image':shot['name']+'.png','size':shot['actual_framebuffer'],'page':shot.get('page'),'zoom':shot['zoom'],'full_resolution':shot['full_resolution'],'text_samples':samples,'focus_samples':focus,'expected_text_controls':expected,'expected_text_count':len(expected),'measured_text_count':len(samples),'intentionally_not_rendered':not_rendered,'omitted_text_controls':omissions,'minimum_text_ratio':min((s['ratio_min'] for s in samples),default=None),'minimum_focus_ratio':min((s['ratio'] for s in focus),default=None)})
    result={'method':'Direct unmodified native PNG samples. Expected theme ink locates the strongest actual interior glyph-core pixel; max-channel distance<=3 is near-solid and4..48 is explicitly reported strongest antialiased core. Button border/focus interiors and RichTextLabel scrollbars are excluded; ratios use sampled RGB, not constants. Missing interior cores are explicitly reported, not counted as passes. RichTextLabel scrollbar/stylebox regions are excluded from glyph evidence. Adjacent stable3x3 rendered backing samples include texture variation in local22×14pixel annulus; minimum and maximum retained. Non-fullcoverage antialias fringes excluded from numerical ratio but visually reviewed separately. Luminance sRGB<=0.04045: c/12.92; else((c+0.055)/1.055)^2.4; Y=.2126R+.7152G+.0722B; ratio=(Ylight+.05)/(Ydark+.05).','reports':reports,'failed_text':[{'image':r['image'],'sample':s} for r in reports for s in r['text_samples'] if not s['pass_5_0']],'failed_focus':[{'image':r['image'],'sample':s} for r in reports for s in r['focus_samples'] if not s['pass_3_0']]}
    (a.folder/'PIXEL-CONTRAST.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
    print(json.dumps({'images':len(reports),'journal_images':sum(r['surface']=='journal' for r in reports),'map_caption_images':sum(r['surface']=='map-caption' for r in reports),'expected_text_controls':sum(r['expected_text_count'] for r in reports),'text_samples':sum(len(r['text_samples']) for r in reports),'focus_samples':sum(len(r['focus_samples']) for r in reports),'minimum_text_ratio':min(r['minimum_text_ratio'] for r in reports if r['minimum_text_ratio'] is not None),'minimum_focus_ratio':min(r['minimum_focus_ratio'] for r in reports if r['minimum_focus_ratio'] is not None),'strongest_antialiased_core_samples':sum(s['actual_glyph_core']['coverage_class']=='strongest-rendered-antialiased-core' for r in reports for s in r['text_samples']),'omitted_text_controls':sum(len(r['omitted_text_controls']) for r in reports),'failed_text':len(result['failed_text']),'failed_focus':len(result['failed_focus'])},indent=2))
if __name__=='__main__':main()
